/** Diagonal bands in the cube's local space that scroll with frame time. */
export const StripeMaterial = materialType({
    name: "ScrollingStripes",
    parameters: StripeParameters,
    defaults: {
        colorA: d.vec3f(0.72, 0.4, 0.05),
